@app.patch("/todos/{todo_id}")
def update_todo(todo_id: int, payload: TodoUpdate) -> Todo:
    if todo_id not in todos:
        raise HTTPException(status_code=404, detail="Todo not found")
    updated = todos[todo_id].model_copy(update={"done": payload.done})
    todos[todo_id] = updated
    return updated

def test_mark_todo_done():
    client.post("/todos", json={"title": "Buy milk"})
    response = client.patch("/todos/1", json={"done": True})
    assert response.status_code == 200
    assert response.json() == {"id": 1, "title": "Buy milk", "done": True}

def test_update_missing_todo_returns_404():
    response = client.patch("/todos/99", json={"done": True})
    assert response.status_code == 404

def test_create_rejects_empty_title():
    response = client.post("/todos", json={"title": ""})
    assert response.status_code == 422

def test_create_todo():
    response = client.post("/todos", json={"title": "Buy milk"})
    assert response.status_code == 201
    assert response.json() == {"id": 1, "title": "Buy milk", "done": False, "priority": 3}

def test_create_todo_rejects_priority_above_5():
    response = client.post("/todos", json={"title": "Pay rent", "priority": 6})
    assert response.status_code == 422

def list_todos(limit: int = 50, offset: int = 0) -> list[Todo]:
    items = list(todos.values())
    return items[offset : offset + limit]

def test_list_todos_with_limit():
    for title in ["a", "b", "c"]:
        client.post("/todos", json={"title": title})
    response = client.get("/todos", params={"limit": 2})
    assert response.status_code == 200
    assert [t["title"] for t in response.json()] == ["a", "b"]

def list_todos(limit: int = 50, offset: int = 0) -> list[Todo]:
    items = list(todos.values())
    return items[offset : offset + limit]

@app.get("/todos/stats")
def todo_stats() -> dict[str, int]:
    total = len(todos)
    done = sum(1 for t in todos.values() if t.done is not None)
    return {"total": total, "done": done}

